385: int CheckKeyCodes(std::string &keyName, MMKeyCode *key) {
386:     if (!key)
387:         return -1;
388: 
389:     if (keyName.length() == 1) {
390:         *key = keyCodeForChar(*keyName.c_str());
391:         return 0;
392:     }
393: 
394:     *key = K_NOT_A_KEY;
395: 
396:     KeyNames *kn = key_names;
397:     while (kn->name) {
398:         if (keyName.compare(kn->name) == 0) {
399:             *key = kn->key;
400:             break;
401:         }
402:         kn++;
403:     }
404: 
405:     if (*key == K_NOT_A_KEY) {
406:         return -2;
407:     }
408: 
409:     return 0;
410: }
