412: int CheckKeyFlags(std::string &flagString, MMKeyFlags *flags) {
413:     if (!flags)
414:         return -1;
415: 
416:     if (flagString == "alt" || flagString == "right_alt") {
417:         *flags = MOD_ALT;
418: #if defined(IS_MACOSX)
419:     } else if (flagString == "command" || flagString == "cmd" || flagString == "right_cmd") {
420:         *flags = MOD_META;
421: #else
422:         } else if (flagString == "command" || flagString == "win" || flagString == "right_win") {
423:     *flags = MOD_META;
424: #endif
425:     } else if (flagString == "control" || flagString == "right_control") {
426:         *flags = MOD_CONTROL;
427:     } else if (flagString == "shift" || flagString == "right_shift") {
428:         *flags = MOD_SHIFT;
429:     } else if (flagString == "fn") {
430:         *flags = MOD_FN;
431:     } else if (flagString == "none") {
432:         *flags = MOD_NONE;
433:     } else {
434:         return -2;
435:     }
436: 
437:     return 0;
438: }
