445: int GetFlagsFromValue(Napi::Value value, MMKeyFlags *flags) {
446:     if (!flags)
447:         return -1;
448: 
449:     //Optionally allow an array of flag strings to be passed.
450:     if (value.IsArray()) {
451:         Napi::Array a = value.As<Napi::Array>();
452:         for (uint32_t i = 0; i < a.Length(); ++i) {
453:             Napi::Value v = a.Get(i);
454:             if (!v.IsString())
455:                 return -2;
456: 
457:             MMKeyFlags f = MOD_NONE;
458:             const int rv = GetFlagsFromString(v, &f);
459:             if (rv)
460:                 return rv;
461: 
462:             *flags = (MMKeyFlags) (*flags | f);
463:         }
464:         return 0;
465:     }
466: 
467:     //If it's not an array, it should be a single string value.
468:     return GetFlagsFromString(value, flags);
469: }
