471: Napi::Number _keyTap(const Napi::CallbackInfo &info) {
472:     Napi::Env env = info.Env();
473: 
474:     MMKeyFlags flags = MOD_NONE;
475:     MMKeyCode key;
476: 
477:     std::string keyName = info[0].As<Napi::String>();
478: 
479:     switch (info.Length()) {
480:         case 2:
481:             switch (GetFlagsFromValue(info[1], &flags)) {
482:                 case -1:
483:                     throw Napi::Error::New(env, "Null pointer in key flag.");
484:                     break;
485:                 case -2:
486:                     throw Napi::Error::New(env, "Invalid key flag specified.");
487:                     break;
488:             }
489:             break;
490:         case 1:
491:             break;
492:         default:
493:             throw Napi::Error::New(env, "Invalid number of arguments.");
494:     }
495: 
496:     switch (CheckKeyCodes(keyName, &key)) {
497:         case -1:
498:             throw Napi::Error::New(env, "Null pointer in key code.");
499:             break;
500:         case -2:
501:             throw Napi::Error::New(env, "Invalid key code specified.");
502:             break;
503:         default:
504:             tapKeyCode(key, flags);
505:     }
506: 
507:     return Napi::Number::New(env, 1);
508: }
