510: Napi::Number _keyToggle(const Napi::CallbackInfo &info) {
511:     Napi::Env env = info.Env();
512: 
513:     MMKeyFlags flags = MOD_NONE;
514:     MMKeyCode key;
515: 
516:     bool down = false;
517: 
518:     //Get arguments from JavaScript.
519:     std::string keyName = info[0].As<Napi::String>();
520: 
521:     //Check and confirm number of arguments.
522:     switch (info.Length()) {
523:         case 3:
524:             //Get key modifier.
525:             switch (GetFlagsFromValue(info[2], &flags)) {
526:                 case -1:
527:                     throw Napi::Error::New(env, "Null pointer in key flag.");
528:                     break;
529:                 case -2:
530:                     throw Napi::Error::New(env, "Invalid key flag specified.");
531:                     break;
532:             }
533:             break;
534:         case 2:
535:             break;
536:         default:
537:             throw Napi::Error::New(env, "Invalid number of arguments.");
538:     }
539: 
540:     //Get down value if provided.
541:     if (info.Length() > 1) {
542:         std::string directionString = info[1].As<Napi::String>();
543: 
544:         if (directionString.compare("down") == 0) {
545:             down = true;
546:         } else if (directionString.compare("up") == 0) {
547:             down = false;
548:         } else {
549:             throw Napi::Error::New(env, "Invalid key state specified.");
550:         }
551:     }
552: 
553:     //Get the acutal key.
554:     switch (CheckKeyCodes(keyName, &key)) {
555:         case -1:
556:             throw Napi::Error::New(env, "Null pointer in key code.");
557:             break;
558:         case -2:
559:             throw Napi::Error::New(env, "Invalid key code specified.");
560:             break;
561:         default:
562:             toggleKeyCode(key, down, flags);
563:     }
564: 
565:     return Napi::Number::New(env, 1);
566: }
