732:     if (!sizeObject.Has("width") || !sizeObject.Has("height")) {
733:         throw Napi::TypeError::New(env,
734:                                    "Invalid second parameter. Expected object of shape {width: number, height: number}");
735:     }
736: 
737:     auto width = sizeObject.Get("width").As<Napi::Number>().Int64Value();
738:     auto height = sizeObject.Get("height").As<Napi::Number>().Int64Value();
739: 
740:     auto newSize = MMSizeMake(width, height);
741: 
742:     auto resizeResult = resizeWindow(windowHandle, newSize);
743: 
744:     return Napi::Boolean::New(env, resizeResult);
745: }
