771: Napi::Object _captureScreen(const Napi::CallbackInfo &info) {
772:     Napi::Env env = info.Env();
773: 
774:     int64_t x;
775:     int64_t y;
776:     int64_t w;
777:     int64_t h;
778: 
779:     MMSize displaySize = getMainDisplaySize();
780:     //If user has provided screen coords, use them!
781:     if (info.Length() == 4) {
782:         x = info[0].As<Napi::Number>().Int64Value();
783:         y = info[1].As<Napi::Number>().Int64Value();
784:         w = info[2].As<Napi::Number>().Int64Value();
785:         h = info[3].As<Napi::Number>().Int64Value();
786: 
787:         if (!(x >= 0 && x <= displaySize.width)) {
788:             throw Napi::Error::New(env, "Error: x coordinate outside of display");
789:         }
790:         if (!(y >= 0 && y <= displaySize.height)) {
791:             throw Napi::Error::New(env, "Error: y coordinate outside of display");
792:         }
793:         if (!((x + w) >= 0 && (x + w) <= displaySize.width)) {
794:             throw Napi::Error::New(env, "Error: Given width exceeds display dimensions");
795:         }
796:         if (!((y + h) >= 0 && (y + h) <= displaySize.height)) {
797:             throw Napi::Error::New(env, "Error: Given height exceeds display dimensions");
798:         }
799:     } else {
800:         //We're getting the full screen.
801:         x = 0;
802:         y = 0;
803: 
804:         //Get screen size.
805:         w = displaySize.width;
806:         h = displaySize.height;
807:     }
808: 
809:     MMBitmapRef bitmap = copyMMBitmapFromDisplayInRect(MMRectMake(x, y, w, h));
810: 
811:     if (bitmap == NULL) {
812:         throw Napi::Error::New(env, "Error: Failed to capture screen");
813:     }
814: 
815:     uint64_t bufferSize = bitmap->bytewidth * bitmap->height;
816:     Napi::Buffer<char> buffer = Napi::Buffer<char>::Copy(env, (char *) bitmap->imageBuffer, bufferSize);
817: 
818:     Napi::Object obj = Napi::Object::New(env);
819:     obj.Set(Napi::String::New(env, "width"), Napi::Number::New(env, (double) bitmap->width));
820:     obj.Set(Napi::String::New(env, "height"), Napi::Number::New(env, (double) bitmap->height));
821:     obj.Set(Napi::String::New(env, "byteWidth"), Napi::Number::New(env, (double) bitmap->bytewidth));
822:     obj.Set(Napi::String::New(env, "bitsPerPixel"), Napi::Number::New(env, bitmap->bitsPerPixel));
823:     obj.Set(Napi::String::New(env, "bytesPerPixel"), Napi::Number::New(env, bitmap->bytesPerPixel));
824:     obj.Set(Napi::String::New(env, "image"), buffer);
825: 
826:     destroyMMBitmap(bitmap);
827: 
828:     return obj;
