102: 			n = c;
103: 		}
104: 		else if ((c & 0xE0) == 0xC0)
105: 		{
106: 			// 110xxxxx two bytes
107: 			c1 = (*str++) & 0x3F;
108: 			n = ((c & 0x1F) << 6) | c1;
109: 		}
