void typeString(const char *str) {
  unsigned short c;
  unsigned short c1;
  unsigned short c2;
  unsigned short c3;
  unsigned long n;

  while (*str != '\0') {
    c = *str++;

    // warning, the following utf8 decoder
    // doesn't perform validation
    if (c <= 0x7F) {
      // 0xxxxxxx one byte
      n = c;
    } else if ((c & 0xE0) == 0xC0) {
      // 110xxxxx two bytes
      c1 = (*str++) & 0x3F;
      n = ((c & 0x1F) << 6) | c1;
    } else if ((c & 0xF0) == 0xE0) {
      // 1110xxxx three bytes
